3e — &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;D&#233;placement.html&quot; title=&quot;D&#233;placement&quot;&gt;d&#233;placement&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;&#201;ruption-De-Pustules.html&quot; title=&quot;&#201;ruption de pustules&quot;&gt;&#233;ruption de pustules&lt;/a&gt;&lt;/i&gt;  (DD 18), &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Innombrables-Yeux.html&quot; title=&quot;Innombrables yeux&quot;&gt;innombrables yeux&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Protection-Contre-Les-&#201;nergies-Destructives.html&quot; title=&quot;Protection contre les &#233;nergies destructives&quot;&gt;protection contre les &#233;nergies destructives&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Rapidit&#233;.html&quot; title=&quot;Rapidit&#233;&quot;&gt;rapidit&#233;&lt;/a&gt;&lt;/i&gt;
&lt;/div&gt;
&lt;div class=&quot;BDsorts&quot;&gt;
2e — &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;D&#233;tection-De-Linvisibilit&#233;.html&quot; title=&quot;D&#233;tection de l&amp;#39;invisibilit&#233;&quot;&gt;d&#233;tection de l&#39;invisibilit&#233;&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Injection.html&quot; title=&quot;Injection&quot;&gt;injection&lt;/a&gt;&lt;/i&gt; , &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;R&#233;sistance-Aux-&#201;nergies-Destructives.html&quot; title=&quot;R&#233;sistance aux &#233;nergies destructives&quot;&gt;r&#233;sistance aux &#233;nergies destructives&lt;/a&gt;&lt;/i&gt; (2), &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Transmission-Alchimique.html&quot; title=&quot;Transmission alchimique&quot;&gt;transmission alchimique&lt;/a&gt;&lt;/i&gt; , &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Vomir-Une-Nu&#233;e.html&quot; title=&quot;Vomir une nu&#233;e&quot;&gt;vomir une nu&#233;e&lt;/a&gt;&lt;/i&gt; 
&lt;/div&gt;
&lt;div class=&quot;BDsorts&quot;&gt;
1er — &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Anticipation-Du-Danger.html&quot; title=&quot;Anticipation du danger&quot;&gt;anticipation du danger&lt;/a&gt;&lt;/i&gt;  (DD 16), &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bouclier.html&quot; title=&quot;Bouclier&quot;&gt;bouclier&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Coup-Au-But.html&quot; title=&quot;Coup au but&quot;&gt;coup au but&lt;/a&gt;&lt;/i&gt; (2), &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;N&#233;gation-De-Lar&#244;me.html&quot; title=&quot;N&#233;gation de l&amp;#39;ar&#244;me&quot;&gt;n&#233;gation de l&#39;ar&#244;me&lt;/a&gt;&lt;/i&gt; , &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Œil-Du-Mitrailleur.html&quot; title=&quot;Œil du mitrailleur&quot;&gt;œil du mitrailleur&lt;/a&gt;&lt;/i&gt; , &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Panac&#233;e-Universelle.html&quot; title=&quot;Panac&#233;e universelle&quot;&gt;panac&#233;e universelle&lt;/a&gt;&lt;/i&gt;  (DD 16)
&lt;/div&gt;
&lt;div class=&quot;BDsoustitre&quot;&gt;Tactique&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Avant le combat.&lt;/b&gt; L’empoisonneur boit son mutag&#232;ne de Dext&#233;rit&#233; et ses extraits d’anticipation du danger, innombrables yeux et invisibilit&#233; supr&#234;me.
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Statistiques de base.&lt;/b&gt; Voici les statistiques de l’empoisonneur sans le mutag&#232;ne de Dext&#233;rit&#233; ni les extraits d’anticipation du danger et d’innombrables yeux : Init +7 ; Sens pas de vision &#224; 360&#176; ; CA 21, contact 14, pris au d&#233;pourvu 18 ; R&#233;f +12, Sag +6 ; Distance arbal&#232;te de poing, +13 (1d4/19-20 plus poison) ou bombe, +12/+7 (6d6+5 feu) ; Dex 17, Sag 12 ; DMD 23 ; Comp&#233;tences Discr&#233;tion +14, Perception +18, Premiers secours +10, Sabotage +17, Survie +10, Vol +11
&lt;/div&gt;
&lt;div class=&quot;BDsoustitre&quot;&gt;Caract&#233;ristiques&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;For&lt;/b&gt; 10, &lt;b&gt;Dex&lt;/b&gt; 21, &lt;b&gt;Con&lt;/b&gt; 12, &lt;b&gt;Int&lt;/b&gt; 20, &lt;b&gt;Sag&lt;/b&gt; 10, &lt;b&gt;Cha&lt;/b&gt; 10
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;BBA&lt;/b&gt; +9 ; &lt;b&gt;BMO&lt;/b&gt; +9 ; &lt;b&gt;DMD&lt;/b&gt; 25
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Dons&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Arme-En-Main.html&quot; title=&quot;Arme en main&quot;&gt;Arme en main&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Bombes-Suppl&#233;mentaires.html&quot; title=&quot;Bombes suppl&#233;mentaires&quot;&gt;Bombes suppl&#233;mentaires&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Lancer-Improvis&#233;.html&quot; title=&quot;Lancer improvis&#233;&quot;&gt;Lancer improvis&#233;&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Pr&#233;paration-De-Potions.html&quot; title=&quot;Pr&#233;paration de potions&quot;&gt;Pr&#233;paration de potions&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Science-De-Linitiative.html&quot; title=&quot;Science de l&amp;#39;initiative&quot;&gt;Science de l&#39;initiative&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Tir-&#192;-Bout-Portant.html&quot; title=&quot;Tir &#224; bout portant&quot;&gt;Tir &#224; bout portant&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Tir-De-Pr&#233;cision.html&quot; title=&quot;Tir de pr&#233;cision&quot;&gt;Tir de pr&#233;cision&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Tir-Rapide.html&quot; title=&quot;Tir rapide&quot;&gt;Tir rapide&lt;/a&gt;
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Comp&#233;tences&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Art-De-La-Magie.html&quot; title=&quot;Art de la magie&quot;&gt;Art de la magie&lt;/a&gt; +20, &lt;a class=&quot;pagelink&quot; href=&quot;Artisanat.html&quot; title=&quot;Artisanat&quot;&gt;Artisanat&lt;/a&gt; (alchimie) +20, &lt;a class=&quot;pagelink&quot; href=&quot;Connaissances.html&quot; title=&quot;Connaissances&quot;&gt;Connaissances&lt;/a&gt; (myst&#232;res) +20, &lt;a class=&quot;pagelink&quot; href=&quot;Connaissances.html&quot; title=&quot;Connaissances&quot;&gt;Connaissances&lt;/a&gt; (nature) +14, &lt;a class=&quot;pagelink&quot; href=&quot;Discr&#233;tion.html&quot; title=&quot;Discr&#233;tion&quot;&gt;Discr&#233;tion&lt;/a&gt; +16, &lt;a class=&quot;pagelink&quot; href=&quot;Perception.html&quot; title=&quot;Perception&quot;&gt;Perception&lt;/a&gt; +17, &lt;a class=&quot;pagelink&quot; href=&quot;Premiers-Secours.html&quot; title=&quot;Premiers secours&quot;&gt;Premiers secours&lt;/a&gt; +9, &lt;a class=&quot;pagelink&quot; href=&quot;Sabotage.html&quot; title=&quot;Sabotage&quot;&gt;Sabotage&lt;/a&gt; +19, &lt;a class=&quot;pagelink&quot; href=&quot;Survie.html&quot; title=&quot;Survie&quot;&gt;Survie&lt;/a&gt; +9, &lt;a class=&quot;pagelink&quot; href=&quot;Utilisation-Dobjets-Magiques.html&quot; title=&quot;Utilisation d&amp;#39;objets magiques&quot;&gt;Utilisation d&#39;objets magiques&lt;/a&gt; +15, &lt;a class=&quot;pagelink&quot; href=&quot;Vol.html&quot; title=&quot;Vol&quot;&gt;Vol&lt;/a&gt; +13
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Langues&lt;/b&gt; commun des profondeurs, elfique
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Particularit&#233;s&lt;/b&gt; alchimie (alchimie +12, identification de potions), d&#233;couvertes (bombe explosive, bombe rapide, bombe empoisonn&#233;e (12 rounds/niveau), bombe fumig&#232;ne, bombe mitrailleuse, ailes AM), mutag&#232;ne (+4/-2, +2 naturelle, 120 minutes), utilisation des poisons, alchimie rapide, empoisonnement rapide
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;&#201;quipement de combat&lt;/b&gt; &lt;i&gt;potions de &lt;a class=&quot;pagelink&quot; href=&quot;Soins-Importants.html&quot; title=&quot;Soins importants&quot;&gt;soins importants&lt;/a&gt;&lt;/i&gt; (2), &lt;i&gt;potion d’&lt;a class=&quot;pagelink&quot; href=&quot;&#201;tat-Gazeux.html&quot; title=&quot;&#201;tat gazeux&quot;&gt;&#233;tat gazeux&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;potion de &lt;a class=&quot;pagelink&quot; href=&quot;D&#233;guisement-Fantomatique.html&quot; title=&quot;D&#233;guisement fantomatique&quot;&gt;d&#233;guisement fantomatique&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;potion d&#39;&lt;a class=&quot;pagelink&quot; href=&quot;Invisibilit&#233;.html&quot; title=&quot;Invisibilit&#233;&quot;&gt;invisibilit&#233;&lt;/a&gt;&lt;/i&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Poisons.html#MORTELAME&quot; title=&quot;Les poisons  &quot;&gt;mortelame&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Poisons.html#BILEDEDRAGON&quot; title=&quot;Les poisons  &quot;&gt;bile de dragon&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Poisons.html#POISONDROW&quot; title=&quot;Les poisons  &quot;&gt;poison drow&lt;/a&gt; (4), &lt;a class=&quot;pagelink&quot; href=&quot;Poisons.html#VENINDEVERPOURPRE&quot; title=&quot;Les poisons  &quot;&gt;venin de ver pourpre&lt;/a&gt; ; &lt;b&gt;&#201;quipement divers&lt;/b&gt; &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Chemise-De-Mailles-(Armure).html&quot; title=&quot;Chemise de mailles&quot;&gt;chemise de mailles&lt;/a&gt; +2&lt;/i&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Arbal&#232;te-De-Poing-(Arme).html&quot; title=&quot;Arbal&#232;te de poing&quot;&gt;arbal&#232;te de poing&lt;/a&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques-Des-Armes#Armesmaitre.html&quot; title=&quot;arme de ma&#238;tre&quot;&gt;de ma&#238;tre&lt;/a&gt; avec 20 &lt;a class=&quot;pagelink&quot; href=&quot;Carreaux-Darbal&#232;te-(Arme).html&quot; title=&quot;Carreaux d&amp;#39;arbal&#232;te (10)&quot;&gt;carreaux&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Rapi&#232;re-(Arme).html&quot; title=&quot;Rapi&#232;re&quot;&gt;rapi&#232;re&lt;/a&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques-Des-Armes#Armesmaitre.html&quot; title=&quot;arme de ma&#238;tre&quot;&gt;de ma&#238;tre&lt;/a&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Amulette-Darmure-Naturelle.html&quot; title=&quot;Amulette d&amp;#39;armure naturelle&quot;&gt;amulette d’armure naturelle&lt;/a&gt; +1&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Ceinturon-De-Dext&#233;rit&#233;-Du-Chat.html&quot; title=&quot;Ceinturon de dext&#233;rit&#233; du chat&quot;&gt;ceinturon de dext&#233;rit&#233; du chat&lt;/a&gt; +2&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Cape-De-R&#233;sistance.html&quot; title=&quot;Cape de r&#233;sistance&quot;&gt;cape de r&#233;sistance&lt;/a&gt; +1&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bandeau-Dintelligence.html&quot; title=&quot;Bandeau d&amp;#39;intelligence&quot;&gt;bandeau d’intelligence&lt;/a&gt; +2&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Anneau-De-Protection.html&quot; title=&quot;Anneau de protection&quot;&gt;anneau de protection&lt;/a&gt; +1&lt;/i&gt;, 170 po
